<script>
document.addEventListener('click', function (e) {
  var b = e.target.closest('[data-hb-rule]'); if (!b) return;
  var on = !b.classList.contains('on'); b.classList.toggle('on', on); b.setAttribute('aria-pressed', on);
  SL.post('ajax/sl/notification_rules_ajax.php', { op: 'toggle', event: b.getAttribute('data-event'), channel: b.getAttribute('data-channel'), value: on ? 1 : 0 }).then(function (j) { SL.toast(j.message || '', !j.success); if (!j.success) b.classList.toggle('on', !on); });
});
</script>
